// Minimal Chart.js DataLabels plugin shim for local dev
// This provides a lightweight plugin object so pages depending on
// ChartDataLabels can register it without failing. It does not
// implement full datalabels features; replace with official build
// in production if you need full functionality.
(function(){
  var plugin = {
    id: 'chartjs-plugin-datalabels',
    beforeInit: function(chart){
      // no-op shim
    }
  };
  // expose global symbol expected by existing code
  try {
    window.ChartDataLabels = plugin;
  } catch(e) {
    // ignore
  }
  // also register automatically if Chart is present
  if (typeof Chart !== 'undefined' && Chart && Chart.register) {
    try { Chart.register(plugin); } catch(e) {}
  }
})();
